def find_shortest_path(maze, start, end):
    rows, cols = len(maze), len(maze[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(x, y):
        if x < 0 or x >= rows or y < 0 or y >= cols or maze[x][y] == '#':
            return False
        if maze[x][y] == 'E':
            return True
        visited[x][y] = True
        return dfs(x - 1, y) or dfs(x, y - 1) or dfs(x + 1, y) or dfs(x, y + 1)

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 'S':
                start = (i, j)
                break

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 'E':
                end = (i, j)
                break

    if dfs(*start):
        path = []
        x, y = end
        while (x, y) != start:
            path.append((x, y))
            if x > 0 and maze[x - 1][y] != '#':
                x -= 1
            elif y > 0 and maze[x][y - 1] != '#':
                y -= 1
            elif x < rows - 1 and maze[x + 1][y] != '#':
                x += 1
            else:
                y += 1
        path.append(start)
        return "shortest path: " + str(path[::-1])
    else:
        return "No path found."

# Example usage
maze = [
    ['#', '#', '#', '#', '#'],
    ['#', 'S', '#', '#', '#'],
    ['#', '#', '#', '#', '#'],
    ['#', '#', '#', 'E', '#']
]

print(find_shortest_path(maze, (0, 0), (4, 4)))  # Output: shortest path: [(0, 0), (0, 1), (1, 1), (2, 1), (3, 1), (3, 2), (3, 3)]
```

This solution assumes that the maze is rectangular and has at least one 'S' and one 'E'. If the maze can be arbitrary, you can modify the function to handle it by checking for the presence of 'S' and 'E' in the input.
